 for(let i=1;i<xs.length;i++){const intervals=pieces.filter(n=>n.rect[0]<xs[i]&&n.rect[2]>xs[i-1]).map(n=>[n.rect[1],n.rect[3]]).sort((a,b)=>a[0]-b[0]);let top=0,bottom=0,height=0;for(const [a,b]of intervals){if(a>bottom){height+=bottom-top;top=a;bottom=b;}else bottom=Math.max(bottom,b);}height+=bottom-top;covered+=(xs[i]-xs[i-1])*height;}return {ratio:size>0?covered/size:0,ownerIds:[...new Set(pieces.map(n=>n.id))]};
