function measuredBaseTypography(rect,pixels,rules,paper,width,height,sx,sy){
 const l=Math.max(0,Math.ceil(rect[0]*sx)+2),r=Math.min(width,Math.floor(rect[2]*sx)-2),t=Math.max(0,Math.ceil(rect[1]*sy)+2),b=Math.min(height,Math.floor(rect[3]*sy)-2),bands=[];let start=-1,last=-1;
 for(let y=t;y<=b+2;y++){let count=0;if(y<b)for(let x=l;x<r;x++){const i=(y*width+x)*4,channels=[pixels[i],pixels[i+1],pixels[i+2]];if(!rules[i+3]&&Math.max(...channels)-Math.min(...channels)<45&&paper[i]-pixels[i]>30)count++;}if(count>=2&&count<(r-l)*.85){if(start<0)start=y;last=y;}else if(start>=0&&y-last>1){if(last-start>=2)bands.push(last-start+1);start=-1;}}
 const heights=bands.filter(h=>h>2).sort((a,b)=>a-b);return heights.length?{fontSize:Math.max(5,Math.min(32,heights[Math.floor(heights.length/2)]/sy/.82)),sourceLines:heights.length}:null;
}

