for(let y=0;y<c.height;y++){let x=0;while(x<c.width){const i=(y*c.width+x)*4,blocked=protectedZones.some(r=>(x+.5)/sx>=r[0]&&(x+.5)/sx<r[2]&&(y+.5)/sy>=r[1]&&(y+.5)/sy<r[3]);if(!data[i+3]||blocked){x++;continue;}const start=x,color=[data[i],data[i+1],data[i+2],data[i+3]];x++;while(x<c.width){const j=(y*c.width+x)*4;if(protectedZones.some(r=>(x+.5)/sx>=r[0]&&(x+.5)/sx<r[2]&&(y+.5)/sy>=r[1]&&(y+.5)/sy<r[3])||color.some((v,k)=>data[j+k]!==v))break;x++;}keptInk+=x-start;parts.push('<rect x="'+start+'" y="'+y+'" width="'+(x-start)+'" height="1" fill="rgb('+color.slice(0,3).join(',')+')" fill-opacity="'+color[3]/255+'"/>');}}
